import { useEffect, useState } from "react";
import { fetchReports } from "../../api/api";

export default function Reports() {
  const [data, setData] = useState({});

  useEffect(() => {
    fetchReports().then(setData);
  }, []);

  return <h2>Total Revenue: ₹{data.total_revenue}</h2>;
}
